import { screen, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest'
import { mockFetch } from './test/fetch'
import { renderAt } from './test/render'

beforeEach(() => {
  Object.defineProperty(navigator, 'clipboard', {
    configurable: true,
    value: { writeText: vi.fn(async () => undefined) },
  })
})
afterEach(() => { vi.unstubAllGlobals() })

const me = { id: 7, email: 'ada@example.com' }

describe('copy debug', () => {
  test('links load', async () => {
    const fetch = mockFetch((method, path) => {
      console.log('FETCH:', method, path)
      if (path === '/api/me') return { body: me }
      if (path === '/healthz') return { body: { status: 'ok' } }
      if (path === '/api/links') return {
        body: [
          { slug: 'alpha', targetURL: 'https://example.com/a', createdAt: '2026-09-01T00:00:00Z', totalClicks: 12 },
          { slug: 'bravo', targetURL: 'https://example.com/b', createdAt: '2026-08-01T00:00:00Z', totalClicks: 0 },
        ],
      }
      return { status: 404, body: { error: 'not found' } }
    })
    renderAt('/links')
    await waitFor(() => {
      const items = screen.getAllByRole('listitem')
      expect(items.length).toBe(2)
    }, { timeout: 3000 })
  })
})
EOF
